previewCss:
.darma-loader-darma-b10-blinking-caret { --accent: var(--loader-color, #64748b); --accent-2: var(--loader-secondary-color, #22c55e); width: var(--loader-size, 90px); height: calc(var(--loader-size, 90px) * .4); display: flex; align-items: center; justify-content: center; gap: calc(var(--loader-size, 90px) * .06); }
.darma-loader-darma-b10-blinking-caret span { width: calc(var(--loader-size, 90px) * .1); height: calc(var(--loader-size, 90px) * .1); border-radius: 50%; background: var(--accent); opacity: .3; animation: darma-loader-darma-b10-blinking-caret-type calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b10-blinking-caret span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b10-blinking-caret span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b10-blinking-caret i { width: calc(var(--loader-size, 90px) * .035); height: 68%; background: var(--accent-2); animation: darma-loader-darma-b10-blinking-caret-blink calc(var(--loader-speed, 1s) * .9) step-end infinite; }
@keyframes darma-loader-darma-b10-blinking-caret-type { 0%, 100% { opacity: .3; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-24%); } }
@keyframes darma-loader-darma-b10-blinking-caret-blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }

